COMP = next(p for p in (Path('/kaggle/input/competitions/enveda-CASMI26-molecule-id-mass-spectra'),
                        Path('/kaggle/input/enveda-CASMI26-molecule-id-mass-spectra'),
                        Path('/kaggle/input/enveda-casmi26-molecule-id-mass-spectra')) if (p / 'train.parquet').is_file())
FOLDS = IR.find('/kaggle/input', 'casmi26-identity-disjoint-validation-folds/structures.parquet')
assert FOLDS, 'Attach dmitriigluzdov/casmi26-natural-product-panel-benchmark (identity folds)'
print('RDKit', rdBase.rdkitVersion, '| inputs', json.dumps(P), '| folds', FOLDS, '| competition', COMP)